/**
 * `GeoModelBase.java`: the runtime's `MsmGeoModel` (GeckoLib 5, Minecraft 26.3) as a base
 * class that takes the three resource ids, so each entity's model is a constructor call.
 *
 * @packageDocumentation
 */

/**
 * The source of `<package>/client/entity/GeoModelBase.java`.
 *
 * @param modelPackage - The client entity package (`<mod package>.client.entity`).
 */
export function geoModelBaseJava(modelPackage: string): string {
  return `// Generated by MCSuperMods: the GeckoLib model of msm_runtime (MsmGeoModel).
package ${modelPackage};

import com.geckolib.animatable.GeoAnimatable;
import com.geckolib.model.GeoModel;
import com.geckolib.renderer.base.GeoRenderState;
import net.minecraft.resources.Identifier;

/**
 * Resource ids for one entity type. GeckoLib keys loaded files by their path with
 * {@code geckolib/models/} or {@code geckolib/animations/} and the {@code .geo.json} or
 * {@code .animation.json} suffix stripped, so {@code assets/ns/geckolib/models/entity/x.geo.json}
 * is {@code ns:entity/x}. Textures are full paths ({@code ns:textures/entity/x.png}).
 */
public class GeoModelBase<T extends GeoAnimatable> extends GeoModel<T> {
    private final Identifier model;
    private final Identifier animations;
    private final Identifier texture;

    protected GeoModelBase(Identifier model, Identifier animations, Identifier texture) {
        this.model = model;
        this.animations = animations;
        this.texture = texture;
    }

    @Override
    public Identifier getModelResource(GeoRenderState renderState) {
        return model;
    }

    @Override
    public Identifier getTextureResource(GeoRenderState renderState) {
        return texture;
    }

    @Override
    public Identifier getAnimationResource(T animatable) {
        return animations;
    }
}
`;
}
